"""
Test edge cases for the control state fix.
"""

import pennylane as qml

def test_edge_cases():
    """Test edge cases for control state visualization."""

    print("=== Edge Case 1: Single control wire ===")
    dev1 = qml.device('default.qubit', wires=2)

    @qml.qnode(dev1)
    def circ1():
        qml.Hadamard(wires=0)
        qml.MultiControlledX([0], 1, '0')  # Single control, state 0
        qml.MultiControlledX([0], 1, '1')  # Single control, state 1
        return qml.probs(0)

    print(qml.draw(circ1)())

    print("\n=== Edge Case 2: Two control wires ===")
    dev2 = qml.device('default.qubit', wires=3)

    @qml.qnode(dev2)
    def circ2():
        qml.Hadamard(wires=0)
        qml.Hadamard(wires=1)
        qml.MultiControlledX([0, 1], 2, '01')
        qml.MultiControlledX([0, 1], 2, '10')
        return qml.probs(0)

    print(qml.draw(circ2)())

    print("\n=== Edge Case 3: Mixed standard and custom controls ===")
    dev3 = qml.device('default.qubit', wires=4)

    @qml.qnode(dev3)
    def circ3():
        qml.Hadamard(wires=0)
        qml.Hadamard(wires=1)
        qml.Hadamard(wires=2)
        qml.CNOT(wires=[0, 3])  # Standard control
        qml.MultiControlledX([1, 2], 3, '01')  # Custom control
        return qml.probs(0)

    print(qml.draw(circ3)())

if __name__ == "__main__":
    test_edge_cases()"}
